// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  random,
  Easing,
  Img,
} from '../remotionShim';
/* -------------------------------------------------------------------------- */
/*                            Google Fonts Loader                             */
/* -------------------------------------------------------------------------- */
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

/* -------------------------------------------------------------------------- */
/*                                 Schema                                     */
/* -------------------------------------------------------------------------- */


export type DreamBubbleProps = Record<string, any>;

/* -------------------------------------------------------------------------- */
/*                              Helper Components                             */
/* -------------------------------------------------------------------------- */

// Generates the fluffy cloud border particles
const CloudParticle: React.FC<{
  index: number;
  total: number;
  radiusX: number;
  radiusY: number;
  color: string;
  glowColor: string;
  popProgress: number;
  baseScale: number;
}> = ({ index, total, radiusX, radiusY, color, glowColor, popProgress, baseScale }) => {
  // Deterministic positioning around an ellipse
  const angle = (index / total) * Math.PI * 2;
  const seed = `cloud-part-${index}`;
  
  // Add randomness to position to make it "fluffy"
  const offsetR = interpolate(random(seed), [0, 1], [-20, 20]);
  const angleOffset = interpolate(random(seed + "a"), [0, 1], [-0.2, 0.2]);
  
  const finalAngle = angle + angleOffset;
  const x = (radiusX + offsetR) * Math.cos(finalAngle);
  const y = (radiusY + offsetR) * Math.sin(finalAngle);

  // Particle Size randomness
  // Increased size range to ensure more overlap with the image
  const size = interpolate(random(seed + "size"), [0, 1], [100, 180]) * baseScale;

  // Pop Animation (Explosion/Smoke effect)
  // Particles move OUTWARD from center
  const explosionDistance = interpolate(popProgress, [0, 1], [0, 300 * baseScale]);
  const smokeX = x + Math.cos(finalAngle) * explosionDistance;
  const smokeY = y + Math.sin(finalAngle) * explosionDistance;
  
  // Smoke characteristics: Scale up, Fade out, Blur
  const smokeScale = interpolate(popProgress, [0, 1], [1, 2.5]);
  const smokeOpacity = interpolate(popProgress, [0, 0.5, 1], [1, 0.8, 0]);
  const smokeBlur = interpolate(popProgress, [0, 1], [0, 20]);

  return (
    <div
      style={{
        position: "absolute",
        left: `calc(50% + ${smokeX}px)`,
        top: `calc(50% + ${smokeY}px)`,
        width: size,
        height: size,
        borderRadius: "50%",
        backgroundColor: color,
        transform: `translate(-50%, -50%) scale(${smokeScale})`,
        opacity: smokeOpacity,
        filter: `blur(${smokeBlur}px) drop-shadow(0 0 15px ${glowColor})`,
        boxShadow: `inset -10px -10px 20px rgba(0,0,0,0.05)`, // Subtle depth
      }}
    />
  );
};

// Generates the small trail bubbles below the cloud
const TrailBubble: React.FC<{
  index: number;
  cloudY: number;
  popProgress: number;
  color: string;
  glowColor: string;
  frame: number;
}> = ({ index, cloudY, popProgress, color, glowColor, frame }) => {
  const seed = `trail-${index}`;
  const size = interpolate(random(seed), [0, 1], [20, 40]);
  const xOffset = interpolate(random(seed + "x"), [0, 1], [-30, 30]);
  const yLag = (index + 1) * 60; // Distance below main cloud

  // Swaying motion
  const sway = Math.sin(frame / 20 + index) * 10;
  
  // Pop effect for trail
  const scale = interpolate(popProgress, [0, 0.2], [1, 0], { extrapolateRight: "clamp" });

  return (
    <div
      style={{
        position: "absolute",
        left: `calc(50% + ${xOffset + sway}px)`,
        top: `calc(50% + ${cloudY + yLag}px)`,
        width: size,
        height: size,
        borderRadius: "50%",
        backgroundColor: color,
        transform: `translate(-50%, -50%) scale(${scale})`,
        boxShadow: `0 0 10px ${glowColor}`,
        opacity: scale, // Fade out on pop
      }}
    />
  );
};

/* -------------------------------------------------------------------------- */
/*                               Main Component                               */
/* -------------------------------------------------------------------------- */

const DreamBubble: React.FC<DreamBubbleProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 8,
  imageUrl = "https://malloy.blob.core.windows.net/web/testing/hq720.jpg",
  bubbleColor = "#ffffff",
  glowColor = "rgba(255, 255, 255, 0.6)",
  popPercentage = 0.75,
  floatIntensity = 20,
  bubbleScale = 0.6,
}) => {
  useFontLoader(["Lato"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Basic Setup
  const totalFrames = durationInSeconds * fps;
  const popFrame = totalFrames * popPercentage;
  
  // Calculate Background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 1. Entrance Animation (Spring Scale)
  const entrance = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
    durationInFrames: 40,
  });

  // 2. Floating Animation (Sine Wave)
  // Continues throughout, but we freeze the Y position relative to the pop moment
  // to prevent the explosion origin from drifting weirdly during the pop.
  const floatY = Math.sin(frame / 40) * floatIntensity;
  
  // 3. Pop Animation Logic
  // Using an interpolation based on frames past the popFrame
  const popProgress = interpolate(
    frame,
    [popFrame, popFrame + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.exp) }
  );

  // Cloud Dimensions
  // Modified to be a circle (using min dimension) to satisfy "more circle than oval"
  // Multiplied by bubbleScale to allow user sizing
  const cloudSize = Math.min(width, height) * bubbleScale;
  const cloudWidth = cloudSize;
  const cloudHeight = cloudSize;
  const cloudBaseScale = width / 1920; // Responsive scaling factor

  // Image Dissolve Logic
  // The image should shrink and fade faster than the smoke expands
  const imageScale = interpolate(popProgress, [0, 0.2], [1, 0], { extrapolateRight: "clamp" });
  const imageOpacity = interpolate(popProgress, [0, 0.15], [1, 0], { extrapolateRight: "clamp" });

  // Generate Cloud Particles (Border)
  // We use a stable array so particles don't re-render/jump
  // Increased count slightly for better circular coverage
  const particleCount = 25;
  const particles = useMemo(() => new Array(particleCount).fill(0), []);
  
  // Trail Bubbles
  const trailBubbles = useMemo(() => new Array(3).fill(0), []);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Container that handles the overall Position + Entrance + Floating */}
      <div
        style={{
          position: "absolute",
          top: "40%",
          left: "50%",
          width: 0,
          height: 0,
          transform: `translate3d(0, ${floatY}px, 0) scale(${entrance})`,
        }}
      >
        {/* --- Layer 1: Trail Bubbles (Below) --- */}
        {trailBubbles.map((_, i) => (
          <TrailBubble
            key={`trail-${i}`}
            index={i}
            cloudY={cloudHeight / 2} // Start below the cloud center
            popProgress={popProgress}
            color={bubbleColor}
            glowColor={glowColor}
            frame={frame}
          />
        ))}

        {/* --- Layer 2: The Custom Image (Inside) --- */}
        {/* Masked by a simple ellipse, hidden by the fluffy border particles */}
        <div
          style={{
            position: "absolute",
            width: cloudWidth,
            height: cloudHeight,
            left: -cloudWidth / 2,
            top: -cloudHeight / 2,
            borderRadius: "50%",
            overflow: "hidden",
            transform: `scale(${imageScale})`,
            opacity: imageOpacity,
            zIndex: 1, // Below particles
            backgroundColor: "#000", // Fallback
          }}
        >
            {/* The Image */}
            <Img
                src={imageUrl}
                style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                }}
            />
        </div>

        {/* --- Layer 3: The Fluffy Border / Smoke Particles --- */}
        {particles.map((_, i) => (
          <CloudParticle
            key={`cloud-${i}`}
            index={i}
            total={particleCount}
            radiusX={cloudWidth / 2}
            radiusY={cloudHeight / 2}
            color={bubbleColor}
            glowColor={glowColor}
            popProgress={popProgress}
            baseScale={cloudBaseScale}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export default DreamBubble;